insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Although water conservation was initially criticized, later evidence showed that it could be useful when applied carefully under careful supervision, as described in a public debate.','The usefulness of water conservation was accepted before anyone criticized it.','Early criticism proved that water conservation had no value at all.','Later evidence showed that water conservation should never be applied.','Later evidence suggested that water conservation, despite early criticism, may have value if used carefully.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_23", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The report does not claim that mobile banking solves every problem; it argues only that it can reduce one specific difficulty after initial trials, as described in a training program.','According to the report, mobile banking is not a complete solution but may help with a particular problem.','The report rejects the idea that mobile banking can help in any way.','The report argues that mobile banking solves all problems completely.','The report discusses many solutions but never mentions a specific problem.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_23", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in schools, as described in an evaluation report in a introductory academic seminar context.','The available data forced the researchers to reject all conclusions.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','The researchers postponed collecting data after reaching a firm conclusion.','The researchers made a recommendation because the data were complete.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_23", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes for adult learners, as described in a committee meeting.','The author claims feedback is useful only when students stop practicing.','The author believes mistakes should be ignored during practice.','The author believes practice works best if learners are told what they did wrong.','The author suggests that practice and feedback are unrelated.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_23", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The new system was adopted not because it was cheaper, but because it made the process more transparent in public institutions, as described in a student guide.','The process became less transparent after the new system was adopted.','The new system was adopted mainly because it reduced costs.','The new system was rejected because it was not transparent.','The main reason for adopting the new system was improved transparency rather than lower cost.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_23", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Even though the experiment was small, its results raised important questions for future research during periods of change, as described in a pilot study.','Despite its limited size, the experiment produced results that future studies should examine.','Future research became unnecessary after the experiment.','The experiment was too large to raise useful questions.','The results were ignored because the experiment was not small.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_23", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The passage implies that convenience may encourage people to use a service, but it does not guarantee satisfaction in small communities, as described in a professional workshop.','The passage says convenience always guarantees satisfaction.','The passage suggests that a convenient service can attract users without necessarily satisfying them.','The passage denies that convenience affects service use.','The passage argues that inconvenient services attract the most users.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_23", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The committee approved the plan only after several risks had been identified and addressed when resources are limited, as described in a policy review.','The committee approved the plan before considering any risks.','The committee rejected the plan because all risks were addressed.','The plan was accepted once the committee had dealt with the risks it found.','The plan was accepted although no risks were identified.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_23", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change under careful supervision, as described in a classroom discussion.','Managers blamed a single change because complaints rose quickly.','The decline in complaints was sudden and easy to explain.','Managers ignored the decline because it was caused by one change.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_23", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
