insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The committee approved the plan only after several risks had been identified and addressed during periods of change, as described in a research summary in a northern education panel context.','The plan was accepted although no risks were identified.','The committee rejected the plan because all risks were addressed.','The plan was accepted once the committee had dealt with the risks it found.','The committee approved the plan before considering any risks.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_25", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in small communities, as described in a public debate in a southern education panel context.','Managers blamed a single change because complaints rose quickly.','The decline in complaints was sudden and easy to explain.','Managers ignored the decline because it was caused by one change.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_25", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The writer contrasts short-term popularity with long-term reliability when resources are limited, as described in a training program in a central education panel context.','The writer points out a difference between being popular now and being dependable over time.','The writer says popularity and reliability are exactly the same.','The writer discusses reliability without mentioning popularity.','The writer argues that long-term reliability is impossible.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_25", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Although public lectures was initially criticized, later evidence showed that it could be useful when applied carefully under careful supervision, as described in an evaluation report.','Early criticism proved that public lectures had no value at all.','Later evidence suggested that public lectures, despite early criticism, may have value if used carefully.','The usefulness of public lectures was accepted before anyone criticized it.','Later evidence showed that public lectures should never be applied.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_25", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The report does not claim that science podcasts solves every problem; it argues only that it can reduce one specific difficulty after initial trials, as described in a committee meeting.','The report rejects the idea that science podcasts can help in any way.','The report argues that science podcasts solves all problems completely.','According to the report, science podcasts is not a complete solution but may help with a particular problem.','The report discusses many solutions but never mentions a specific problem.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_25", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in schools, as described in a student guide in a summer education panel context.','The researchers made a recommendation because the data were complete.','The available data forced the researchers to reject all conclusions.','The researchers postponed collecting data after reaching a firm conclusion.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_25", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes for adult learners, as described in a pilot study in a advanced education panel context.','The author believes practice works best if learners are told what they did wrong.','The author suggests that practice and feedback are unrelated.','The author believes mistakes should be ignored during practice.','The author claims feedback is useful only when students stop practicing.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_25", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The new system was adopted not because it was cheaper, but because it made the process more transparent in public institutions, as described in a professional workshop in a introductory education panel context.','The process became less transparent after the new system was adopted.','The main reason for adopting the new system was improved transparency rather than lower cost.','The new system was rejected because it was not transparent.','The new system was adopted mainly because it reduced costs.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_25", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
