insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The report does not claim that exam simulations solves every problem; it argues only that it can reduce one specific difficulty for adult learners, as described in a student guide.','The report rejects the idea that exam simulations can help in any way.','The report discusses many solutions but never mentions a specific problem.','The report argues that exam simulations solves all problems completely.','According to the report, exam simulations is not a complete solution but may help with a particular problem.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_26", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in public institutions, as described in a pilot study.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','The researchers made a recommendation because the data were complete.','The researchers postponed collecting data after reaching a firm conclusion.','The available data forced the researchers to reject all conclusions.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_26", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes during periods of change, as described in a professional workshop.','The author suggests that practice and feedback are unrelated.','The author believes practice works best if learners are told what they did wrong.','The author believes mistakes should be ignored during practice.','The author claims feedback is useful only when students stop practicing.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_26", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The new system was adopted not because it was cheaper, but because it made the process more transparent in small communities, as described in a policy review.','The new system was adopted mainly because it reduced costs.','The new system was rejected because it was not transparent.','The main reason for adopting the new system was improved transparency rather than lower cost.','The process became less transparent after the new system was adopted.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_26", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'Even though the experiment was small, its results raised important questions for future research when resources are limited, as described in a classroom discussion.','The experiment was too large to raise useful questions.','Future research became unnecessary after the experiment.','The results were ignored because the experiment was not small.','Despite its limited size, the experiment produced results that future studies should examine.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_26", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The committee approved the plan only after several risks had been identified and addressed during periods of change, as described in a training program in a coastal language center context.','The plan was accepted once the committee had dealt with the risks it found.','The committee approved the plan before considering any risks.','The committee rejected the plan because all risks were addressed.','The plan was accepted although no risks were identified.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_27", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
